CREATE TABLE IF NOT EXISTS enrichable.table_types (
  id text PRIMARY KEY,
  definition jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (jsonb_typeof(definition) = 'object')
);

CREATE INDEX IF NOT EXISTS table_types_status_category ON enrichable.table_types ((definition->>'status'), (definition->>'category'), id);

INSERT INTO enrichable.table_types (id, definition) VALUES
('companies', $$
{"id":"companies","entity":"companies","category":"Companies & Organizations","name":"Companies","description":"Discover companies that match a market, location, size, or business description.","instructions":"Use the prompt to identify the company segment, geography, size, and business model. Keep every explicit constraint when forming search queries.","examplePrompts":["Residential solar installers in Texas","B2B software companies with 20–50 employees in the United States"],"requiredInputs":[{"key":"query","label":"Search description","description":"Natural-language description of the records to find.","type":"text","required":true},{"key":"countries","label":"Countries","description":"Optional country filters applied by Monid.","type":"country-list","required":false}],"defaultColumns":[{"name":"Company","field":"Company","width":200},{"name":"Website","field":"Domain","format":"website","width":170},{"name":"Description","field":"Description","width":320},{"name":"Industry","field":"Industry","width":160},{"name":"Headquarters","field":"Headquarters","width":170},{"name":"Employees","field":"Employees","format":"number","width":110},{"name":"Founded","field":"Founded","format":"year","width":90},{"name":"Funding","field":"Funding","format":"currency","width":160},{"name":"Stage","field":"Stage","width":110}],"rowMapping":[{"sourceField":"Company","columnName":"Company"},{"sourceField":"Domain","columnName":"Website"},{"sourceField":"Description","columnName":"Description"},{"sourceField":"Industry","columnName":"Industry"},{"sourceField":"Headquarters","columnName":"Headquarters"},{"sourceField":"Employees","columnName":"Employees"},{"sourceField":"Founded","columnName":"Founded"},{"sourceField":"Funding","columnName":"Funding"},{"sourceField":"Stage","columnName":"Stage"}],"identity":{"sourceField":"Domain","normalization":"domain"},"operations":["company.search"],"pagination":{"strategy":"cursor","maxCalls":20},"chaining":{"enabled":false,"operations":[]},"status":"published"}
$$::jsonb),
('people', $$
{"id":"people","entity":"people","category":"People","name":"People","description":"Find professionals by role, company, location, skills, or background.","instructions":"Use the prompt to identify role, seniority, employer, industry, location, and background. Keep explicit filters together when searching.","examplePrompts":["Heads of growth at Series B fintech companies in the US","Chief executives at companies that recently raised funding"],"requiredInputs":[{"key":"query","label":"Search description","description":"Natural-language description of the records to find.","type":"text","required":true},{"key":"countries","label":"Countries","description":"Optional country filters applied by Monid.","type":"country-list","required":false}],"defaultColumns":[{"name":"Name","field":"Name","width":180},{"name":"Title","field":"Title","width":200},{"name":"Company","field":"Company","width":170},{"name":"Company website","field":"Company domain","format":"website","width":160},{"name":"Location","field":"Location","width":170},{"name":"LinkedIn","field":"LinkedIn","format":"url","width":220},{"name":"Schools","field":"Schools","width":200},{"name":"Skills","field":"Skills","width":220},{"name":"Years of experience","field":"Years of experience","format":"number","width":120},{"name":"Summary","field":"Summary","width":320}],"rowMapping":[{"sourceField":"Name","columnName":"Name"},{"sourceField":"Title","columnName":"Title"},{"sourceField":"Company","columnName":"Company"},{"sourceField":"Company domain","columnName":"Company website"},{"sourceField":"Location","columnName":"Location"},{"sourceField":"LinkedIn","columnName":"LinkedIn"},{"sourceField":"Schools","columnName":"Schools"},{"sourceField":"Skills","columnName":"Skills"},{"sourceField":"Years of experience","columnName":"Years of experience"},{"sourceField":"Summary","columnName":"Summary"}],"identity":{"sourceField":"LinkedIn","normalization":"profile-url"},"operations":["people.search","people.enrich"],"pagination":{"strategy":"cursor","maxCalls":20},"chaining":{"enabled":true,"operations":["people.enrich"]},"status":"published"}
$$::jsonb),
('websites', $$
{"id":"websites","entity":"websites","category":"Web & Websites","name":"Websites","description":"Find web pages matching a topic, phrase, or site-level description.","instructions":"Search for pages that directly match the requested topic. Use distinct phrasing only when the current search results do not fill the requested target.","examplePrompts":["SaaS pricing pages that mention a free tier","Research pages about battery recycling in Europe"],"requiredInputs":[{"key":"query","label":"Search description","description":"Natural-language description of the records to find.","type":"text","required":true},{"key":"countries","label":"Countries","description":"Optional country filters applied by Monid.","type":"country-list","required":false}],"defaultColumns":[{"name":"Webpage","field":"URL","format":"webpage","width":260},{"name":"Title","field":"Title","width":260},{"name":"Description","field":"Description","width":400}],"rowMapping":[{"sourceField":"URL","columnName":"Webpage"},{"sourceField":"Title","columnName":"Title"},{"sourceField":"Description","columnName":"Description"}],"identity":{"sourceField":"URL","normalization":"url"},"operations":["web.search"],"pagination":{"strategy":"queries","maxCalls":20},"chaining":{"enabled":false,"operations":[]},"status":"published"}
